bool write(BitWriter& bits, const SessionUserTransferEvent& value) {
    if (!write(bits, value.header))
        return false;
    if (!write(bits, value.type))
        return false;
    if (!writeUnsigned(bits, value.id, UINT64_C(0), UINT64_C(4294967295), 32))
        return false;
    if (!writeBool(bits, value.last))
        return false;
    if (!writeBool(bits, value.path.has_value()))
        return false;
    if (value.path) {
        if (!writeString(bits, (*value.path), 9, UINT64_C(260)))
            return false;
    }
    return true;
}

bool read(BitReader& bits, SessionUserTransferEvent& value) {
    if (!read(bits, value.header))
        return false;
    if (!read(bits, value.type))
        return false;
    {
        std::uint64_t raw = 0;
        if (!readUnsigned(bits, raw, UINT64_C(0), UINT64_C(4294967295), 32))
            return false;
        value.id = static_cast<std::uint32_t>(raw);
    }
    if (!readBool(bits, value.last))
        return false;
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.path.emplace();
            if (!readString(bits, (*value.path), 9, UINT64_C(260)))
                return false;
        } else {
            value.path.reset();
        }
    }
    return true;
}

