const SystemHeader& systemHeader(const SystemEvent& event) noexcept {
    return std::visit([](const auto& body) -> const SystemHeader& { return body.header; }, event);
}

SystemHeader& systemHeader(SystemEvent& event) noexcept {
    return std::visit([](auto& body) -> SystemHeader& { return body.header; }, event);
}

std::optional<std::size_t> encodeSystemEvent(const SystemEvent& event, std::span<std::byte> out) {
    for (auto& byte : out) {
        byte = std::byte{0};
    }
    BitWriter bits(out);
    if (!writeEvent(bits, event)) {
        return std::nullopt;
    }
    return bits.bytes();
}

StreamDecode decodeSystemStream(std::span<const std::byte> stream) {
    BitReader bits(stream);
    SystemEvent event;
    if (!readEvent(bits, event)) {
        return {bits.exhausted() ? StreamStatus::Truncated : StreamStatus::Bad, 0, std::nullopt};
    }
    if (!bits.paddingClean()) {
        return {StreamStatus::Bad, 0, std::nullopt};
    }
    return {StreamStatus::Complete, bits.consumedBytes(), std::move(event)};
}

std::optional<SystemEvent> decodeSystemEvent(std::span<const std::byte> datagram) {
    auto result = decodeSystemStream(datagram);
    if (result.status != StreamStatus::Complete || result.consumed != datagram.size()) {
        return std::nullopt;
    }
    return std::move(result.event);
}

